function parseMaybeJson(value, fallback = {}) {
  if (value && typeof value === "object") return value;
  if (typeof value !== "string") return fallback;

  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

const execution_context = parseMaybeJson($json.execution_context, {});
const context_packet = parseMaybeJson($json.context_packet, {});
const decision = parseMaybeJson($json.decision, {});
const state_update = parseMaybeJson($json.state_update, {});
const execution_meta = parseMaybeJson($json.execution_meta, {});

const lead_id =
  $json.lead_id ||
  execution_context.lead_id ||
  context_packet?.lead?.id ||
  null;

const channel =
  $json.channel ||
  execution_context.channel ||
  context_packet?.lead?.channel ||
  "whatsapp";

const phone =
  $json.phone ||
  execution_context.phone ||
  context_packet?.lead?.phone ||
  null;

const calendar_id =
  $json.calendar_id ||
  execution_context.calendar_id ||
  null;

const cancellation_reason =
  $json.cancellation_reason ||
  execution_context.cancellation_reason ||
  decision.cancellation_reason ||
  decision.reason ||
  "cancelled_by_client";

const target_appointment_id =
  $json.target_appointment_id ||
  execution_context.target_appointment_id ||
  state_update.target_appointment_id ||
  null;

const agent_id =
  $json.agent_id ||
  execution_context.agent_id ||
  context_packet?.routing?.agent_id ||
  context_packet?.agent?.id ||
  null;

if (!lead_id) {
  throw new Error("Missing lead_id in cancel_booking");
}

return [
  {
    json: {
      lead_id,
      channel,
      phone,
      calendar_id,
      cancellation_reason,
      target_appointment_id,
      agent_id,

      execution_context: {
        ...execution_context,
        lead_id,
        channel,
        phone,
        calendar_id,
        cancellation_reason,
        target_appointment_id,
        agent_id,
        action: "cancel_booking"
      },

      context_packet,
      decision,
      state_update,
      execution_meta,

      notes: ["cancel_booking_input_normalized"]
    }
  }
];

const msg = "No encontre una reserva activa a tu nombre. Si quieres, puedo ayudarte a agendar una nueva.";

return [
  {
    json: {
      ...$json,
      success: true,
      action: "cancel_booking",
      outcome: "no_active_appointment",
      active_appointment_found: false,
      appointment: null,
      message_to_send: msg,
      db_operations: ["messages", "lead_state"],
      state_update: {
        ...($json.state_update || {}),
        last_bot_action: "cancel_booking_no_active_appointment",
        next_goal: "offer_booking",
        missing_fields: []
      },
      execution_result: {
        success: true,
        action: "cancel_booking",
        outcome: "no_active_appointment",
        bot: msg,
        message_sent: false,
        state_updated: true,
        db_records_created: ["messages", "lead_state"],
        notes: ["cancel_booking_no_active_appointment"]
      },
      notes: [...($json.notes || []), "cancel_booking_no_active_appointment"]
    }
  }
];

const eventId = $json.event_id || $json.appointment?.event_id || null;
const hasOfferedSlots = !!$json.combined_cancel_message;
const defaultMsg =
  "Listo, deje cancelada tu reserva. Si mas adelante quieres reagendar, me escribes y revisamos un nuevo horario.";
const msg = $json.combined_cancel_message || defaultMsg;

return [
  {
    json: {
      ...$json,
      success: true,
      action: "cancel_booking",
      outcome: "active_appointment_found",
      active_appointment_found: true,

      message_to_send: msg,

      db_operations: ["appointments", "followups", "messages", "lead_state"],

      state_update: hasOfferedSlots
        ? {
            ...($json.state_update || {}),
            cancellation_reason:
              $json.execution_context?.cancellation_reason || "cancelled_by_client",
            last_appointment_event_id: eventId
          }
        : {
            ...($json.state_update || {}),
            stage: "cancelled",
            next_goal: "reactivate_later",
            last_bot_action: "cancel_booking",
            cancellation_reason:
              $json.execution_context?.cancellation_reason || "cancelled_by_client",
            last_appointment_event_id: eventId,
            missing_fields: []
          },

      execution_result: {
        success: true,
        action: "cancel_booking",
        outcome: "active_appointment_found",
        bot: msg,
        message_sent: false,
        state_updated: true,
        db_records_created: ["appointments", "followups", "messages", "lead_state"],
        notes: [
          "booking_cancelled",
          eventId ? `event_id:${eventId}` : "event_id_missing"
        ]
      },

      notes: [...($json.notes || []), "booking_cancelled"]
    }
  }
];

const original = (() => {
  try {
    return $("cancel_booking").first().json;
  } catch {
    return {};
  }
})();

const { error: _discardedError, ...$jsonSafe } = $json;
const data = {
  ...original,
  ...$jsonSafe,
  execution_context: {
    ...(original.execution_context || {}),
    ...($json.execution_context || {})
  },
  context_packet: $json.context_packet || original.context_packet || {},
  decision: $json.decision || original.decision || {}
};

const outcome =
  data.outcome ||
  data.execution_result?.outcome ||
  data.result?.outcome ||
  (
    data.active_appointment_found === false ||
    data.active_appointment === null ||
    data.appointment === null
      ? "no_active_appointment"
      : "active_appointment_found"
  );

const finalMessage =
  data.message_to_send ||
  data.message ||
  (
    outcome === "no_active_appointment"
      ? "Revise y no encontre una reserva activa asociada a este numero. Si quieres, te puedo ayudar a agendar una nueva hora."
      : "Listo, deje cancelada tu reserva. Si mas adelante quieres reagendar, te puedo ayudar por aqui."
  );

return [{
  ...data,

  action: "cancel_booking",
  outcome,

  message_to_send: finalMessage,
  message: finalMessage,

  db_operations: ["messages", "lead_state"],

  state_update: data.combined_cancel_message
    ? {
        ...(data.state_update || {}),
        missing_fields: Array.isArray(data.state_update?.missing_fields)
          ? data.state_update.missing_fields
          : []
      }
    : {
        ...(data.state_update || {}),
        stage: outcome === "active_appointment_found"
          ? "qualified"
          : data.context_packet?.state?.stage,
        intent_last: outcome,
        next_goal: outcome === "no_active_appointment"
          ? "clarify_or_book"
          : "reactivation",
        last_bot_action: outcome === "no_active_appointment"
          ? "cancel_no_active_appointment"
          : "cancel_booking",
        // Limpiar el horario cancelado: si no, un "ok"/"si" suelto despues
        // puede ser malinterpretado como confirmar esa misma reserva de nuevo.
        booking_date: outcome === "active_appointment_found" ? null : data.state_update?.booking_date,
        booking_time: outcome === "active_appointment_found" ? null : data.state_update?.booking_time,
        slot_id: outcome === "active_appointment_found" ? null : data.state_update?.slot_id,
        availability_confirmed: outcome === "active_appointment_found" ? false : data.state_update?.availability_confirmed,
        booking_options: outcome === "active_appointment_found" ? [] : data.state_update?.booking_options,
        fields_to_clear: outcome === "active_appointment_found"
          ? ["booking_date", "booking_time", "slot_id", "booking_options", "availability_confirmed"]
          : (Array.isArray(data.state_update?.fields_to_clear) ? data.state_update.fields_to_clear : []),
        missing_fields: []
      },

  execution_result: {
    ...(data.execution_result || {}),
    success: true,
    action: "cancel_booking",
    outcome,
    bot: finalMessage
  },

  notes: [
    ...(data.notes || []),
    `cancel_booking_outcome_${outcome}`
  ]
}];

const slotsResult = $json;
const cancelNote = "Listo, cancele tu reserva anterior.";
const slotsMessage = slotsResult.message_to_send || slotsResult.message || "";

const combinedMessage = slotsMessage
  ? `${cancelNote} ${slotsMessage}`
  : cancelNote;

return [
  {
    json: {
      ...slotsResult,
      combined_cancel_message: combinedMessage
    }
  }
];

const original = $("merge_cancel_context_with_appointment").first().json;
const auth = $json || {};

return [{
  json: {
    ...original,
    oauth_connected: auth.connected === true,
    oauth_access_token: auth.access_token || null,
    oauth_calendar_id: auth.calendar_id || null
  }
}];

